// src/screens/HomeScreen.js - главный экран приложения
import React, { useState, useEffect } from 'react';
import { 
  View, 
  Text, 
  TouchableOpacity, 
  StyleSheet, 
  ScrollView,
  ActivityIndicator,
  Alert 
} from 'react-native';
// useStorage для счетчика удаляется, оставляем только если он нужен для других данных,
// но для чистоты кода, удаляем его импорт, т.к. на этом экране он больше не нужен.
// import useStorage from '../hooks/useStorage'; 
import useApi from '../hooks/useApi';
import { apiService } from '../services/apiService';

const HomeScreen = ({ navigation }) => {
  // ❌ УДАЛИТЬ: Логика состояния счетчика и его загрузки
  // const { value: count, setValue: setCount, loading: storageLoading } = useStorage('counter', 0);

  const { data: users, loading: apiLoading, error: apiError, refetch } = useApi(
    'https://jsonplaceholder.typicode.com/users'
  );

  const [localData, setLocalData] = useState([]);
  const [postLoading, setPostLoading] = useState(false);

  const addLocalItem = () => {
    const newItem = {
      id: Date.now(),
      title: `Элемент ${localData.length + 1}`,
      timestamp: new Date().toLocaleTimeString()
    };
    setLocalData(prev => [newItem, ...prev]);
  };

  // ❌ УДАЛИТЬ: Логика инкремента счетчика
  // const incrementCounter = () => {
  //   setCount(prev => prev + 1);
  // };

  const createPost = async () => {
    setPostLoading(true);
    try {
      const newPost = {
        title: 'Новый пост',
        body: 'Это тестовый пост',
        userId: 1
      };

      await new Promise(resolve => setTimeout(resolve, 1000));
      const result = await apiService.createPost(newPost);

      Alert.alert('Успех', `Пост создан! ID: ${result.id}`);
    } catch (e) {
      Alert.alert('Ошибка', `Не удалось создать пост: ${e.message}`);
    } finally {
      setPostLoading(false);
    }
  };

  // ❌ УДАЛИТЬ: Логика сброса счетчика
  // const resetCounter = () => {
  //   setCount(0);
  // };

  // ... (остальной код)

  return (
    <ScrollView style={styles.container}>

      {/* ❌ УДАЛИТЬ: Секция счетчика */}
      {/* <View style={styles.section}>
        <Text style={styles.sectionTitle}>Счетчик</Text>
        <Text style={styles.counter}>
          {storageLoading ? 'Загрузка...' : `Значение: ${count}`}
        </Text>
        <View style={styles.buttonRow}>
          <TouchableOpacity 
            style={[styles.button, { flex: 0.5 }]} 
            onPress={incrementCounter}
          >
            <Text style={styles.navButtonText}>+1</Text>
          </TouchableOpacity>
          <TouchableOpacity 
            style={[styles.button, styles.resetButton, { flex: 0.5 }]} 
            onPress={resetCounter}
          >
            <Text style={styles.navButtonText}>Сбросить</Text>
          </TouchableOpacity>
        </View>
      </View> */}

      {/* Секция API-данных (остается) */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>API-Данные (Пользователи)</Text>

        {/* ... (остальной код API) */}
      </View>

      {/* Секция Локальные данные (остается) */}
      <View style={styles.section}>
        <Text style={styles.sectionTitle}>Локальные данные</Text>
        {/* ... (остальной код локальных данных) */}
      </View>

      {/* Секция Навигация (остается) */}
      <View style={[styles.section, { padding: 5, paddingVertical: 10 }]}>
        <Text style={styles.sectionTitle}>Навигация</Text>
        {/* ... (остальной код навигации) */}
      </View>
    </ScrollView>
  );
};
// ... (стили остаются без изменений)
export default HomeScreen;
